(()=>{const synth=window.speechSynthesis,select=el('devicevoice'),status=el('voicestatus');let voices=[],active=null,utterance=null;
function reset(){if(active){active.textContent=t('voiceListen');active.setAttribute('aria-pressed','false');active=null}}
function stop(){synth?.cancel();utterance=null;reset()}
function populate(){const old=select.value;voices=synth?synth.getVoices().filter(v=>v.localService):[];select.replaceChildren();voices.forEach((v,i)=>{const opt=document.createElement('option');opt.value=String(i);opt.textContent=v.name+' · '+v.lang;select.append(opt)});const chosen=voices.findIndex(v=>v.lang.toLowerCase().startsWith(lang));select.value=chosen>=0?String(chosen):old&&voices[Number(old)]?old:'0';status.textContent=!synth?t('voiceUnsupported'):voices.length?t('voiceLocal'):t('voiceMissing');select.disabled=!voices.length;document.querySelectorAll('.listen-response').forEach(b=>{b.disabled=!voices.length;b.textContent=t('voiceListen');b.setAttribute('aria-label',t('listenAria'))})}
if(synth)synth.addEventListener('voiceschanged',populate);
window.attachListen=(node,text)=>{if(!text.trim())return;const b=document.createElement('button');b.className='listen-response';b.textContent=t('voiceListen');b.setAttribute('aria-label',t('listenAria'));b.setAttribute('aria-pressed','false');b.disabled=!voices.length;b.onclick=()=>{if(active===b){stop();return}stop();const voice=voices[Number(select.value)];if(!voice)return;utterance=new SpeechSynthesisUtterance(text.replace(/\[\d+\]/g,'').replace(/[*#`]/g,''));utterance.voice=voice;utterance.lang=voice.lang;active=b;b.textContent=t('voiceStop');b.setAttribute('aria-pressed','true');utterance.onend=utterance.onerror=()=>{if(active===b)reset()};synth.speak(utterance)};node.append(b)};
el('chatcollapse').addEventListener('click',stop);select.onchange=stop;window.addEventListener('pagehide',stop);window.addEventListener('atlaslanguage',()=>{stop();populate()});populate();})();
